        q=B[i:i+n,j:j+n]
        info=collections.defaultdict(int)
        for S in sym(A):
            for ax in (0,1):
                for s in range(n):
                    tgt=np.roll(S,s,axis=ax)
                    if np.array_equal(tgt,q): info[(nm,S.tobytes())]+=1
        print(nm,'matches:',info)

